package dev.jason.gboardpatches.patches.gboard.features.ioslayout

import app.morphe.patcher.patch.document
import app.morphe.patcher.patch.packageMetadata
import org.w3c.dom.Element

/**
 * Resource-id lookup for the ported iOS layout patches.
 *
 * Gboard ships with obfuscated resource names, so the decoded names are generated by the decoder
 * and may differ between tools. Resources are therefore addressed by their ids, and translated to
 * the decoded names through `public.xml`.
 *
 * The ids used by the bundled XML are those of Gboard 18.5.4, as inherited from
 * twelvehouse/gboard-ios-style-jp-en-morphe-patches (GPLv3). Ids shift between builds, so
 * `/gboard-ios-layouts/ids/<version>.txt` maps them to the ids of the build being patched, and
 * only the builds that have a table are accepted.
 */
internal class GboardLayoutResourceIds private constructor(
    private val names: Map<Long, Pair<String, String>>,
    private val table: Map<Long, Long>,
    private val version: String,
) {

    /** `@type/name` reference for [id]. */
    fun ref(id: Long): String = entry(id).let { (type, name) -> "@$type/$name" }

    /** Decoded file path of a file resource such as a layout or an xml, in the default configuration. */
    fun path(id: Long): String = entry(id).let { (type, name) -> "res/$type/$name.xml" }

    /** Decoded name of [id], for example to build an attribute name such as `app:<name>`. */
    fun name(id: Long): String = entry(id).second

    /**
     * Replaces placeholders so XML bundled with the patches can refer to obfuscated resources:
     * `{{0x7f0e0701}}` becomes the reference `@type/name`, and `{{name:0x7f0405f3}}` the bare name.
     */
    fun expand(text: String): String = PLACEHOLDER.replace(text) { match ->
        val id = match.groupValues[2].removePrefix("0x").toLong(16)
        if (match.groupValues[1] == "name:") name(id) else ref(id)
    }

    private fun entry(id: Long): Pair<String, String> {
        val actual = table[id] ?: error(
            "Resource 0x${id.toString(16)} is missing from the id table of Gboard $version. " +
                "Add it to gboard-ios-layouts/ids/$version.txt",
        )
        return names[actual] ?: error(
            "Resource 0x${actual.toString(16)} is missing from res/values/public.xml",
        )
    }

    companion object {
        private val PLACEHOLDER = Regex("""\{\{(name:)?(0x[0-9a-fA-F]{8})}}""")

        /** Version names end with the ABI, but every ABI build of a version has the same resources. */
        private val ABI_SUFFIX = Regex("-(arm64-v8a|armeabi-v7a|x86_64|x86)$")

        /**
         * Gboard builds with an id table. 18.6.3 is the build this suite targets, so it is the only
         * one admitted: a build without a table would silently resolve the 18.5.4 ids to whatever
         * resource now sits at that id.
         */
        private val ID_TABLES = setOf("18.6.3.1002251336-release")

        /** Reads `public.xml` of the APK being patched. Call it from a patch's execute block. */
        fun read(): GboardLayoutResourceIds {
            val version = packageMetadata.versionName.replace(ABI_SUFFIX, "")
            check(version in ID_TABLES) {
                "Gboard $version has no iOS layout resource-id table. Supported: ${ID_TABLES.joinToString()}"
            }

            val names = HashMap<Long, Pair<String, String>>()
            document("res/values/public.xml").use { document ->
                val publics = document.getElementsByTagName("public")
                for (i in 0 until publics.length) {
                    val element = publics.item(i) as Element
                    val id = element.getAttribute("id").removePrefix("0x").toLongOrNull(16) ?: continue
                    names[id] = element.getAttribute("type") to element.getAttribute("name")
                }
            }
            return GboardLayoutResourceIds(names, readTable(version), version)
        }

        /** Reads `gboard-ios-layouts/ids/<name>.txt`: lines of "<id in 18.5.4> <id in this build>". */
        private fun readTable(name: String): Map<Long, Long> {
            val text = GboardLayoutResourceIds::class.java
                .getResourceAsStream("/gboard-ios-layouts/ids/$name.txt")
                ?.use { stream -> stream.readBytes().toString(Charsets.UTF_8) }
                ?: error("Missing iOS layout resource-id table gboard-ios-layouts/ids/$name.txt")
            return text.lineSequence()
                .map { line -> line.substringBefore('#').trim() }
                .filter { line -> line.isNotEmpty() }
                .associate { line ->
                    val (reference, actual) = line.split(Regex("\\s+"))
                        .map { value -> value.removePrefix("0x").toLong(16) }
                    reference to actual
                }
        }
    }
}
